import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the expansion of (a x + b)^{n}, where a and b are relatively prime positive integers. Suppose the three consecutive coefficients of x^{k-1}, x^{k}, and x^{k+1} form an arithmetic progression. Among all such pairs (a, b), find the minimal possible value of a + b, given n = {n} and k = {k}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# We construct n and k so that the necessary square-root condition is rational:
# (n+1)/((k+1)(n-k+1)) is a perfect square of a rational.
# Strategy: pick m even, set n+1 = m^2, then find u, v with u^2 + v^2 = m^2 + 1 and 2 <= u < m, 2 <= v,
# and choose k+1 = u^2 so that (k+1)(n-k+1) = u^2 v^2 is a square.
for _ in range(200):
    m = rng.randrange(8, 60, 2)  # even m ensures reasonably large n
    S = m*m + 1
    n = S - 2  # so n+1 = m^2
    candidates = []
    # Search for u^2 + v^2 = m^2 + 1 with 2 <= u < m and v >= 2
    for u in range(2, m):
        y = S - u*u
        v = int(math.isqrt(y))
        if v*v == y and v >= 2:
            k = u*u - 1
            if 1 <= k <= n - 1:
                candidates.append((n, k))
    if candidates:
        n, k = rng.choice(candidates)
        return {'n': n, 'k': k}
# Fallback to a known valid pair (m=8, u=4, v=7): n=63, k=15
return {'n': 63, 'k': 15}

    def verifier(assign):
import math
# Validate input
n = assign.get('n')
k = assign.get('k')
if not isinstance(n, int) or not isinstance(k, int):
    # invalid types
    return (False, None)
if n < 3 or not (1 <= k <= n - 1):
    # out of domain
    return (False, None)
# We need (n+1)/((k+1)(n-k+1)) to be a rational square for the arithmetic progression to lead to rational a/b
R_num = n + 1
R_den = (k + 1) * (n - k + 1)
g = math.gcd(R_num, R_den)
num = R_num // g
den = R_den // g
a_sq = int(math.isqrt(num))
b_sq = int(math.isqrt(den))
if a_sq * a_sq != num or b_sq * b_sq != den:
    # Discriminant not a square -> would force irrational a/b; reject (difficulty enforcement)
    return (False, None)
# Compute the two rational candidates for t = a/b from the quadratic condition:
# C(n,k+1) t^2 - 2 C(n,k) t + C(n,k-1) = 0
# This simplifies to t = (k+1)/(n-k) * (1 ± sqrt((n+1)/((k+1)(n-k+1))))
A = k + 1
B = n - k
s_num = a_sq  # sqrt of reduced numerator
s_den = b_sq  # sqrt of reduced denominator
# t_plus = A/B * (s_den + s_num)/s_den
num_plus = A * (s_den + s_num)
den_plus = B * s_den
g1 = math.gcd(num_plus, den_plus)
a1 = num_plus // g1
b1 = den_plus // g1
# Check that (a1,b1) produce an arithmetic progression among the three consecutive coefficients
def check_pair(av, bv):
    if av <= 0 or bv <= 0:
        return False
    ckm1 = math.comb(n, k - 1) * pow(av, k - 1) * pow(bv, n - k + 1)
    ck   = math.comb(n, k)     * pow(av, k)     * pow(bv, n - k)
    ckp1 = math.comb(n, k + 1) * pow(av, k + 1) * pow(bv, n - k - 1)
    return 2 * ck == ckm1 + ckp1
valid_sums = []
if check_pair(a1, b1):
    valid_sums.append(a1 + b1)
# t_minus = A/B * (s_den - s_num)/s_den, only valid if s_den > s_num (to keep positive)
if s_den > s_num:
    num_minus = A * (s_den - s_num)
    den_minus = B * s_den
    g2 = math.gcd(num_minus, den_minus)
    a2 = num_minus // g2
    b2 = den_minus // g2
    if check_pair(a2, b2):
        valid_sums.append(a2 + b2)
if not valid_sums:
    # Shouldn't happen for generated instances; if it does, reject
    return (False, None)
# The problem asks for the minimal possible a+b among valid coprime solutions
answer = min(valid_sums)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

